1	// Transaction Service for managing credit card and bank transactions
2	
3	import type { SupabaseClient } from '@supabase/supabase-js';
4	import type {
5		TransactionRow,
6		TransactionInsert,
7		TransactionUpdate,
8		CreditCardType,
9		ParsedTransaction
10	} from '$lib/models/Transaction';
11	import { CSVParserFactory } from './csvParsers/CSVParserFactory';
12	import { convertExcelToCSV, isExcelFile } from './ExcelToCSVConverter'; // #{#xls2a}
13	import { computeImportPlan, type ExistingTransactionRow } from '$lib/utils/transactionDedup'; // #{#tid2a}
14	
15	export class TransactionService {
16		private supabase: SupabaseClient;
17	
18		constructor(supabase: SupabaseClient) {
19			this.supabase = supabase;
20		}
21	
22		/**
23		 * List transactions for a family with optional filtering and sorting
24		 */
25		async list(
26			familyId: string,
27			options?: {
28				sort?: 'transaction_date' | 'vendor_name' | 'amount' | 'credit_card_type';
29				direction?: 'asc' | 'desc';
30				includeExcluded?: boolean;
31				creditCardType?: CreditCardType;
32			}
33		): Promise<TransactionRow[]> {
34			let query = this.supabase.from('transactions').select('*').eq('family_id', familyId);
35	
36			// Filter excluded transactions
37			if (!options?.includeExcluded) {
38				query = query.eq('excluded', false);
39			}
40	
41			// Filter by credit card type
42			if (options?.creditCardType) {
43				query = query.eq('credit_card_type', options.creditCardType);
44			}
45	
46			// Apply sorting
47			const sortColumn = options?.sort || 'transaction_date';
48			const ascending = options?.direction === 'asc';
49			query = query.order(sortColumn, { ascending });
50	
51			const { data, error } = await query;
52	
53			if (error) {
54				throw new Error(`Failed to load transactions: ${error.message}`);
55			}
56	
57			return data || [];
58		}
59	
60		/**
61		 * Get a single transaction by ID
62		 */
63		async get(id: string): Promise<TransactionRow> {
64			const { data, error } = await this.supabase
65				.from('transactions')
66				.select('*')
67				.eq('id', id)
68				.single();
69	
70			if (error) {
71				throw new Error(`Failed to load transaction: ${error.message}`);
72			}
73	
74			return data;
75		}
76	
77		/**
78		 * Create a new transaction
79		 */
80		async create(transaction: TransactionInsert): Promise<TransactionRow> {
81			const { data, error } = await this.supabase
82				.from('transactions')
83				.insert(transaction)
84				.select()
85				.single();
86	
87			if (error) {
88				throw new Error(`Failed to create transaction: ${error.message}`);
89			}
90	
91			return data;
92		}
93	
94		/**
95		 * Update an existing transaction
96		 */
97		async update(id: string, updates: TransactionUpdate): Promise<TransactionRow> {
98			const { data, error } = await this.supabase
99				.from('transactions')
100				.update(updates)
101				.eq('id', id)
102				.select()
103				.single();
104	
105			if (error) {
106				throw new Error(`Failed to update transaction: ${error.message}`);
107			}
108	
109			return data;
110		}
111	
112		/**
113		 * Delete a transaction
114		 */
115		async delete(id: string): Promise<void> {
116			const { error } = await this.supabase.from('transactions').delete().eq('id', id);
117	
118			if (error) {
119				throw new Error(`Failed to delete transaction: ${error.message}`);
120			}
121		}
122	
123		/**
124		 * Delete multiple transactions by id (selection-based bulk delete).
125		 */
126		async deleteByIds(ids: string[]): Promise<void> {
127			if (ids.length === 0) return;
128			const { error } = await this.supabase.from('transactions').delete().in('id', ids);
129	
130			if (error) {
131				throw new Error(`Failed to delete transactions: ${error.message}`);
132			}
133		}
134	
135		/**
136		 * Toggle the excluded flag on a transaction
137		 */
138		async toggleExcluded(id: string, excluded: boolean): Promise<TransactionRow> {
139			return this.update(id, { excluded });
140		}
141	
142		/**
143		 * Parse CSV/XLS/XLSX file and return parsed transactions - #{#xls2b}
144		 */
145		async parseCSV(
146			file: File,
147			creditCardType: CreditCardType
148		): Promise<{
149			transactions: ParsedTransaction[];
150			errors: string[];
151			detectedType?: CreditCardType;
152		}> {
153			return new Promise((resolve, reject) => {
154				const reader = new FileReader();
155	
156				reader.onload = (e) => {
157					try {
158						let csvContent: string;
159	
160						if (isExcelFile(file)) {
161							const buffer = e.target?.result as ArrayBuffer;
162							csvContent = convertExcelToCSV(buffer);
163						} else {
164							csvContent = e.target?.result as string;
165						}
166	
167						// Get the appropriate parser
168						const parser = CSVParserFactory.getParser(creditCardType);
169	
170						// Validate format
171						if (!parser.validateFormat(csvContent)) {
172							resolve({
173								transactions: [],
174								errors: [
175									`The file does not match the expected format for ${creditCardType}. Please verify you selected the correct credit card type.`
176								]
177							});
178							return;
179						}
180	
181						// Parse the CSV
182						const result = parser.parse(csvContent);
183						resolve({
184							transactions: result.transactions,
185							errors: result.errors
186						});
187					} catch (error: unknown) {
188						const message = error instanceof Error ? error.message : 'Unknown error';
189						reject(new Error(`Failed to parse file: ${message || 'Unknown error'}`));
190					}
191				};
192	
193				reader.onerror = () => {
194					reject(new Error('Failed to read file'));
195				};
196	
197				if (isExcelFile(file)) {
198					reader.readAsArrayBuffer(file);
199				} else {
200					reader.readAsText(file);
201				}
202			});
203		}
204	
205		/**
206		 * Auto-detect file format and parse - #{#xls2c}
207		 */
208		async parseCSVAuto(file: File): Promise<{
209			transactions: ParsedTransaction[];
210			errors: string[];
211			detectedType: CreditCardType | null;
212		}> {
213			return new Promise((resolve, reject) => {
214				const reader = new FileReader();
215	
216				reader.onload = (e) => {
217					try {
218						let csvContent: string;
219	
220						if (isExcelFile(file)) {
221							const buffer = e.target?.result as ArrayBuffer;
222							csvContent = convertExcelToCSV(buffer);
223						} else {
224							csvContent = e.target?.result as string;
225						}
226	
227						// Try to detect the format
228						const detection = CSVParserFactory.detectParser(csvContent);
229	
230						if (!detection) {
231							resolve({
232								transactions: [],
233								errors: [
234									'Could not automatically detect the file format. Please manually select the credit card type.'
235								],
236								detectedType: null
237							});
238							return;
239						}
240	
241						// Parse the CSV
242						const result = detection.parser.parse(csvContent);
243						resolve({
244							transactions: result.transactions,
245							errors: result.errors,
246							detectedType: detection.creditCardType
247						});
248					} catch (error: unknown) {
249						const message = error instanceof Error ? error.message : 'Unknown error';
250						reject(new Error(`Failed to parse file: ${message || 'Unknown error'}`));
251					}
252				};
253	
254				reader.onerror = () => {
255					reject(new Error('Failed to read file'));
256				};
257	
258				if (isExcelFile(file)) {
259					reader.readAsArrayBuffer(file);
260				} else {
261					reader.readAsText(file);
262				}
263			});
264		}
265	
266		/**
267		 * Import transactions from CSV/XLSX using count-based duplicate detection.
268		 *
269		 * Specifications: #{#tid1a} #{#tid2a} #{#tid2b} #{#tid5a}
270		 *
271		 * For each distinct `(transaction_date, vendor_name, amount)` key in the file,
272		 * inserts `max(0, fileCount - dbCount)` rows. Excluded (soft-deleted) rows count
273		 * toward `dbCount` so re-import does not resurrect them.
274		 */
275		async importFromCSV(
276			familyId: string,
277			file: File,
278			creditCardType: CreditCardType
279		): Promise<{
280			imported: number;
281			skipped: number;
282			errors: string[];
283		}> {
284			const parseResult = await this.parseCSV(file, creditCardType);
285	
286			if (parseResult.transactions.length === 0) {
287				return { imported: 0, skipped: 0, errors: parseResult.errors };
288			}
289	
290			const errors: string[] = [...parseResult.errors];
291	
292			// #{#tid2a}: single scoped query for existing rows in the file's date range.
293			// #{#tid2b}: scope to (family_id, credit_card_type).
294			// #{#tid5a}: no excluded filter — excluded rows count toward dbCount.
295			const dates = parseResult.transactions.map((t) => t.transaction_date);
296			const minDate = dates.reduce((a, b) => (a < b ? a : b));
297			const maxDate = dates.reduce((a, b) => (a > b ? a : b));
298	
299			const { data: existingRows, error: selectError } = await this.supabase
300				.from('transactions')
301				.select('transaction_date, vendor_name, amount')
302				.eq('family_id', familyId)
303				.eq('credit_card_type', creditCardType)
304				.gte('transaction_date', minDate)
305				.lte('transaction_date', maxDate);
306	
307			if (selectError) {
308				throw new Error(`Failed to load existing transactions: ${selectError.message}`);
309			}
310	
311			const plan = computeImportPlan(
312				parseResult.transactions,
313				(existingRows ?? []) as ExistingTransactionRow[]
314			);
315	
316			if (plan.toInsert.length === 0) {
317				return { imported: 0, skipped: plan.skipped, errors };
318			}
319	
320			const rowsToInsert = plan.toInsert.map((t) => ({
321				family_id: familyId,
322				transaction_date: t.transaction_date,
323				vendor_name: t.vendor_name,
324				amount: t.amount,
325				credit_card_type: creditCardType
326			}));
327	
328			const { error: insertError } = await this.supabase.from('transactions').insert(rowsToInsert);
329	
330			if (insertError) {
331				errors.push(`Failed to insert transactions: ${insertError.message}`);
332				return { imported: 0, skipped: plan.skipped, errors };
333			}
334	
335			return { imported: plan.toInsert.length, skipped: plan.skipped, errors };
336		}
337	
338		/**
339		 * Get transaction statistics for a family
340		 */
341		async getStats(familyId: string): Promise<{
342			totalTransactions: number;
343			totalAmount: number;
344			byCardType: Record<string, { count: number; total: number }>;
345		}> {
346			const transactions = await this.list(familyId, { includeExcluded: false });
347	
348			const stats = {
349				totalTransactions: transactions.length,
350				totalAmount: 0,
351				byCardType: {} as Record<string, { count: number; total: number }>
352			};
353	
354			for (const transaction of transactions) {
355				stats.totalAmount += transaction.amount;
356	
357				if (!stats.byCardType[transaction.credit_card_type]) {
358					stats.byCardType[transaction.credit_card_type] = { count: 0, total: 0 };
359				}
360	
361				stats.byCardType[transaction.credit_card_type].count++;
362				stats.byCardType[transaction.credit_card_type].total += transaction.amount;
363			}
364	
365			return stats;
366		}
367	
368		/**
369		 * Delete all transactions for a family (with optional filters) - #{#tbd1b}
370		 */
371		async deleteAll(
372			familyId: string,
373			options?: {
374				creditCardType?: CreditCardType;
375				beforeDate?: string;
376				afterDate?: string;
377			}
378		): Promise<number> {
379			// Count matching transactions before deleting
380			let countQuery = this.supabase
381				.from('transactions')
382				.select('id', { count: 'exact', head: true })
383				.eq('family_id', familyId);
384	
385			if (options?.creditCardType) {
386				countQuery = countQuery.eq('credit_card_type', options.creditCardType);
387			}
388			if (options?.afterDate) {
389				countQuery = countQuery.gte('transaction_date', options.afterDate);
390			}
391			if (options?.beforeDate) {
392				countQuery = countQuery.lt('transaction_date', options.beforeDate);
393			}
394	
395			const { count } = await countQuery;
396	
397			// Delete with the same filters
398			let deleteQuery = this.supabase.from('transactions').delete().eq('family_id', familyId);
399	
400			if (options?.creditCardType) {
401				deleteQuery = deleteQuery.eq('credit_card_type', options.creditCardType);
402			}
403			if (options?.afterDate) {
404				deleteQuery = deleteQuery.gte('transaction_date', options.afterDate);
405			}
406			if (options?.beforeDate) {
407				deleteQuery = deleteQuery.lt('transaction_date', options.beforeDate);
408			}
409	
410			const { error } = await deleteQuery;
411	
412			if (error) {
413				throw new Error(`Failed to delete transactions: ${error.message}`);
414			}
415	
416			return count || 0;
417		}
418	}
