1	import { describe, it, expect, beforeEach, vi } from 'vitest';
2	import type { SupabaseClient } from '@supabase/supabase-js';
3	
4	/**
5	 * CategoryService Test Suite
6	 *
7	 * Tests for #{#exp3a} - Family Category Management
8	 *
9	 * Specification: specs/specifications/expense-categorization.md
10	 * Authority: developer
11	 * Priority: High
12	 *
13	 * Requirements:
14	 * 1. Categories must be scoped to families (family_id foreign key)
15	 * 2. New families must receive a default set of common categories on creation
16	 * 3. Default categories must include the full list defined in CategoryService
17	 * 4. Family members must be able to create custom categories
18	 * 5. Family members must be able to rename existing categories (affects all expenses in category)
19	 * 6. Family members must be able to delete categories (with confirmation if expenses exist in category)
20	 * 7. Category names must be unique per family (case-insensitive)
21	 * 8. Categories must support optional color coding for visual distinction
22	 */
23	
24	// Mock Supabase client
25	const createMockSupabaseClient = (): SupabaseClient => {
26		const mockQuery = {
27			data: null,
28			error: null,
29			select: vi.fn().mockReturnThis(),
30			eq: vi.fn().mockReturnThis(),
31			insert: vi.fn().mockReturnThis(),
32			update: vi.fn().mockReturnThis(),
33			delete: vi.fn().mockReturnThis(),
34			single: vi.fn(function (this: any) {
35				// When single() is called, return data directly (not in array)
36				if (Array.isArray(this.data) && this.data.length > 0) {
37					return Promise.resolve({ data: this.data[0], error: this.error });
38				}
39				return Promise.resolve({ data: this.data, error: this.error });
40			}),
41			order: vi.fn().mockReturnThis(),
42			returns: vi.fn().mockReturnThis(),
43			then: vi.fn(function (this: any, resolve) {
44				// Make the query object thenable for async/await
45				return resolve({ data: this.data, error: this.error });
46			})
47		};
48	
49		return {
50			from: vi.fn().mockReturnValue(mockQuery),
51			rpc: vi.fn().mockResolvedValue({ data: null, error: null }),
52			auth: {
53				getSession: vi.fn().mockResolvedValue({ data: { session: { user: { id: 'test-user-id' } } } })
54			}
55		} as any;
56	};
57	
58	describe('CategoryService - #{#exp3a} User Category Management', () => {
59		let mockSupabase: SupabaseClient;
60		let CategoryService: any;
61	
62		beforeEach(async () => {
63			mockSupabase = createMockSupabaseClient();
64	
65			// Dynamic import to avoid module not found errors during RED phase
66			try {
67				const module = await import('./CategoryService');
68				CategoryService = module.CategoryService;
69			} catch (error) {
70				// Expected to fail during RED phase - service doesn't exist yet
71				CategoryService = null;
72			}
73		});
74	
75		describe('Requirement 1: Categories scoped to families', () => {
76			it('should query categories filtered by family_id', async () => {
77				if (!CategoryService) {
78					expect.fail('CategoryService not implemented yet (RED phase expected)');
79					return;
80				}
81	
82				const service = new CategoryService(mockSupabase);
83				const familyId = 'test-family-123';
84	
85				await service.getFamilyCategories(familyId);
86	
87				// Verify query filters by family_id
88				const mockFrom = mockSupabase.from('categories') as any;
89				expect(mockSupabase.from).toHaveBeenCalledWith('categories');
90				expect(mockFrom.eq).toHaveBeenCalledWith('family_id', familyId);
91			});
92	
93			it('should only return categories belonging to the specified family', async () => {
94				if (!CategoryService) {
95					expect.fail('CategoryService not implemented yet (RED phase expected)');
96					return;
97				}
98	
99				const mockCategories = [
100					{ id: 'cat-1', family_id: 'family-123', name: 'Groceries', color: '#10B981' },
101					{ id: 'cat-2', family_id: 'family-123', name: 'Dining', color: '#F59E0B' }
102				];
103	
104				const mockFrom = mockSupabase.from('categories') as any;
105				mockFrom.data = mockCategories;
106				mockFrom.error = null;
107	
108				const service = new CategoryService(mockSupabase);
109				const categories = await service.getFamilyCategories('family-123');
110	
111				expect(categories).toHaveLength(2);
112				expect(categories[0].family_id).toBe('family-123');
113				expect(categories[1].family_id).toBe('family-123');
114			});
115	
116			it('should throw error if familyId is not provided', async () => {
117				if (!CategoryService) {
118					expect.fail('CategoryService not implemented yet (RED phase expected)');
119					return;
120				}
121	
122				const service = new CategoryService(mockSupabase);
