import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { TransactionService } from '../TransactionService';
import type { CreditCardType, ParsedTransaction } from '$lib/models/Transaction';

/**
 * Tests for the DB-query half of TransactionService.importFromCSV.
 *
 * The pure planner (computeImportPlan) is covered in transactionDedup tests.
 * These tests lock the query the service issues to build `dbCount`:
 *
 * - #{#tid2b}: the existing-rows query is scoped to (family_id, credit_card_type),
 *   so identical transactions on a different card / family are counted separately
 *   and are NOT deduped against each other.
 * - #{#tid5a}: the query does NOT filter out excluded rows, so excluded
 *   (soft-deleted) rows still count toward dbCount and re-import does not
 *   resurrect them.
 */

type SupabaseQueryBuilder = ReturnType<SupabaseClient['from']>;

const CARD: CreditCardType = 'PC Financial';

/**
 * Builds a mock Supabase client whose `transactions` table supports both the
 * select chain used to load existing rows and the insert used to write new rows.
 * Every chain method is an individually inspectable mock so a test can assert on
 * the exact filters applied.
 */
function makeMockSupabase(existingRows: ParsedTransaction[]) {
	const selectLte = vi.fn().mockResolvedValue({ data: existingRows, error: null });
	const selectGte = vi.fn().mockReturnValue({ lte: selectLte });
	const selectEqCard = vi.fn().mockReturnValue({ gte: selectGte });
	const selectEqFamily = vi.fn().mockReturnValue({ eq: selectEqCard });
	const select = vi.fn().mockReturnValue({ eq: selectEqFamily });
	const insert = vi.fn().mockResolvedValue({ error: null });

	const from = vi.fn().mockReturnValue({
		select,
		insert
	} as unknown as SupabaseQueryBuilder);

	const supabase = { from } as unknown as SupabaseClient;

	return { supabase, from, select, selectEqFamily, selectEqCard, selectGte, selectLte, insert };
}

/** Collects the argument pairs of every `.eq(...)` call across the select chain. */
function eqCalls(mocks: {
	selectEqFamily: ReturnType<typeof vi.fn>;
	selectEqCard: ReturnType<typeof vi.fn>;
}): unknown[][] {
	return [...mocks.selectEqFamily.mock.calls, ...mocks.selectEqCard.mock.calls];
}

describe('TransactionService.importFromCSV - dedup query scoping', () => {
	let file: File;

	beforeEach(() => {
		vi.clearAllMocks();
		// parseCSV is spied per-test, so the file content is never read.
		file = new File(['ignored'], 'import.csv', { type: 'text/csv' });
	});

	it('#{#tid2b}: scopes the existing-rows query to family_id AND credit_card_type', async () => {
		const mocks = makeMockSupabase([]);
		const service = new TransactionService(mocks.supabase);

		vi.spyOn(service, 'parseCSV').mockResolvedValue({
			transactions: [{ transaction_date: '2026-01-10', vendor_name: 'Coffee', amount: -4.5 }],
			errors: []
		});

		await service.importFromCSV('family-1', file, CARD);

		expect(mocks.from).toHaveBeenCalledWith('transactions');
		// Only the match-key columns are selected — no row/state columns.
		expect(mocks.select).toHaveBeenCalledWith('transaction_date, vendor_name, amount');
		// Scoped per family and per card.
		expect(mocks.selectEqFamily).toHaveBeenCalledWith('family_id', 'family-1');
		expect(mocks.selectEqCard).toHaveBeenCalledWith('credit_card_type', CARD);
		// Date window comes from the file's min/max transaction_date.
		expect(mocks.selectGte).toHaveBeenCalledWith('transaction_date', '2026-01-10');
		expect(mocks.selectLte).toHaveBeenCalledWith('transaction_date', '2026-01-10');
	});

	it('#{#tid2b}: same key on a different card is NOT deduped (scoped query returns no match)', async () => {
		// The card being imported has no existing rows for this key. A row with the
		// identical key exists on another card, but the scoped query never sees it,
		// so the transaction is inserted rather than skipped.
		const mocks = makeMockSupabase([]);
		const service = new TransactionService(mocks.supabase);

		const parsed: ParsedTransaction = {
			transaction_date: '2026-02-01',
			vendor_name: 'Gas Station',
			amount: -60
		};
		vi.spyOn(service, 'parseCSV').mockResolvedValue({ transactions: [parsed], errors: [] });

		const result = await service.importFromCSV('family-1', file, CARD);

		expect(mocks.selectEqCard).toHaveBeenCalledWith('credit_card_type', CARD);
		expect(result).toEqual({ imported: 1, skipped: 0, errors: [] });
		expect(mocks.insert).toHaveBeenCalledTimes(1);
		expect(mocks.insert).toHaveBeenCalledWith([
			{
				family_id: 'family-1',
				transaction_date: '2026-02-01',
				vendor_name: 'Gas Station',
				amount: -60,
				credit_card_type: CARD
			}
		]);
	});

	it('#{#tid5a}: the dbCount query does NOT filter out excluded rows', async () => {
		const mocks = makeMockSupabase([]);
		const service = new TransactionService(mocks.supabase);

		vi.spyOn(service, 'parseCSV').mockResolvedValue({
			transactions: [{ transaction_date: '2026-03-05', vendor_name: 'Store', amount: -12 }],
			errors: []
		});

		await service.importFromCSV('family-1', file, CARD);

		// No filter narrows the count by exclusion state.
		const allEqCalls = eqCalls(mocks);
		expect(allEqCalls).not.toContainEqual(['excluded', false]);
		expect(allEqCalls.some((call) => call[0] === 'excluded')).toBe(false);
	});

	it('#{#tid5a}: a previously-excluded matching row counts toward dbCount (not resurrected)', async () => {
		// The DB query (which does not exclude soft-deleted rows) returns the
		// matching row. computeImportPlan therefore skips the re-imported row: the
		// file has 1, dbCount is 1, so 0 are inserted.
		const existing: ParsedTransaction = {
			transaction_date: '2026-04-01',
			vendor_name: 'Subscription',
			amount: -9.99
		};
		const mocks = makeMockSupabase([existing]);
		const service = new TransactionService(mocks.supabase);

		vi.spyOn(service, 'parseCSV').mockResolvedValue({
			transactions: [{ ...existing }],
			errors: []
		});

		const result = await service.importFromCSV('family-1', file, CARD);

		expect(result).toEqual({ imported: 0, skipped: 1, errors: [] });
		expect(mocks.insert).not.toHaveBeenCalled();
	});

	it('inserts only the surplus over dbCount for duplicated keys', async () => {
		// File has the same key twice; DB already has one. Only one net row inserts.
		const key: ParsedTransaction = {
			transaction_date: '2026-05-01',
			vendor_name: 'Lunch',
			amount: -20
		};
		const mocks = makeMockSupabase([{ ...key }]);
		const service = new TransactionService(mocks.supabase);

		vi.spyOn(service, 'parseCSV').mockResolvedValue({
			transactions: [{ ...key }, { ...key }],
			errors: []
		});

		const result = await service.importFromCSV('family-1', file, CARD);

		expect(result).toEqual({ imported: 1, skipped: 1, errors: [] });
		expect(mocks.insert).toHaveBeenCalledTimes(1);
		expect(mocks.insert).toHaveBeenCalledWith([
			{
				family_id: 'family-1',
				transaction_date: '2026-05-01',
				vendor_name: 'Lunch',
				amount: -20,
				credit_card_type: CARD
			}
		]);
	});

	it('throws when the existing-rows query fails', async () => {
		const selectLte = vi
			.fn()
			.mockResolvedValue({ data: null, error: { message: 'boom' } });
		const selectGte = vi.fn().mockReturnValue({ lte: selectLte });
		const selectEqCard = vi.fn().mockReturnValue({ gte: selectGte });
		const selectEqFamily = vi.fn().mockReturnValue({ eq: selectEqCard });
		const select = vi.fn().mockReturnValue({ eq: selectEqFamily });
		const from = vi.fn().mockReturnValue({ select } as unknown as SupabaseQueryBuilder);
		const supabase = { from } as unknown as SupabaseClient;

		const service = new TransactionService(supabase);
		vi.spyOn(service, 'parseCSV').mockResolvedValue({
			transactions: [{ transaction_date: '2026-06-01', vendor_name: 'X', amount: -1 }],
			errors: []
		});

		await expect(service.importFromCSV('family-1', file, CARD)).rejects.toThrow(
			'Failed to load existing transactions: boom'
		);
	});

	it('returns parse errors without querying when the file has no transactions', async () => {
		const mocks = makeMockSupabase([]);
		const service = new TransactionService(mocks.supabase);

		vi.spyOn(service, 'parseCSV').mockResolvedValue({
			transactions: [],
			errors: ['bad format']
		});

		const result = await service.importFromCSV('family-1', file, CARD);

		expect(result).toEqual({ imported: 0, skipped: 0, errors: ['bad format'] });
		expect(mocks.from).not.toHaveBeenCalled();
	});
});

import { describe, it, expect, beforeEach, vi } from 'vitest';
import type { SupabaseClient } from '@supabase/supabase-js';
import { TransactionService } from '../TransactionService';

/**
 * Tests for TransactionService.deleteByIds - the selection-based bulk delete.
 *
 * The method issues a single `delete().in('id', ids)` query. Row-level scoping
 * to the authed user's family is enforced by Supabase RLS (there is no explicit
 * family filter in the query), so these tests assert the exact query shape the
 * service produces and its error / empty-list handling.
 */

type SupabaseQueryBuilder = ReturnType<SupabaseClient['from']>;

function makeMockSupabase(error: { message: string } | null = null) {
	const inFn = vi.fn().mockResolvedValue({ error });
	const del = vi.fn().mockReturnValue({ in: inFn });
	const from = vi.fn().mockReturnValue({ delete: del } as unknown as SupabaseQueryBuilder);
	const supabase = { from } as unknown as SupabaseClient;
	return { supabase, from, del, inFn };
}

describe('TransactionService.deleteByIds', () => {
	beforeEach(() => {
		vi.clearAllMocks();
	});

	it('deletes exactly the given ids in a single IN query', async () => {
		const mocks = makeMockSupabase();
		const service = new TransactionService(mocks.supabase);
		const ids = ['txn-1', 'txn-2', 'txn-3'];

		await service.deleteByIds(ids);

		expect(mocks.from).toHaveBeenCalledTimes(1);
		expect(mocks.from).toHaveBeenCalledWith('transactions');
		expect(mocks.del).toHaveBeenCalledTimes(1);
		expect(mocks.inFn).toHaveBeenCalledTimes(1);
		expect(mocks.inFn).toHaveBeenCalledWith('id', ids);
	});

	it('does nothing for an empty id list', async () => {
		const mocks = makeMockSupabase();
		const service = new TransactionService(mocks.supabase);

		await expect(service.deleteByIds([])).resolves.toBeUndefined();

		expect(mocks.from).not.toHaveBeenCalled();
	});

	it('throws when Supabase returns an error', async () => {
		const mocks = makeMockSupabase({ message: 'permission denied' });
		const service = new TransactionService(mocks.supabase);

		await expect(service.deleteByIds(['txn-1'])).rejects.toThrow(
			'Failed to delete transactions: permission denied'
		);
	});
});
